const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point([-122.107805, 39.493523]);
    const geometry = point.buffer(16093.4); // 10 miles in meters

    const startDate1 = '2021-08-20';
    const endDate1 = '2021-09-19';
    const startDate2 = '2022-09-01';
    const endDate2 = '2022-10-01';

    // 2. Data Acquisition & Processing Function
    const getNdvi = (startDate, endDate, geometry) => {
        // Sentinel-2 cloud masking function
        const maskS2clouds = (image) => {
            const qa = image.select('QA60');
            const cloudBitMask = 1 << 10;
            const cirrusBitMask = 1 << 11;
            let mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
            return image.updateMask(mask).divide(10000)
                .select("B[2-8]*")
                .copyProperties(image, ["system:time_start"]);
        };

        let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterDate(startDate, endDate)
            .filterBounds(geometry)
            .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 25));

        // Fallback to Landsat 8 if Sentinel-2 is empty
        if (collection.size().getInfo() === 0) {
            collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                .filterDate(startDate, endDate)
                .filterBounds(geometry);

            const qaMask = (image) => {
                const qa = image.select('QA_PIXEL');
                const cloud = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4));
                return image.updateMask(cloud.not());
            };
            const applyScaleFactors = (image) => {
                const opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
                return image.addBands(opticalBands, null, true);
            };

            const l8_collection = collection.map(qaMask).map(applyScaleFactors);
            const l8_image = l8_collection.median();
            if (l8_image.bandNames().size().getInfo() === 0) return null;
            return l8_image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
        }

        const s2_image = collection.map(maskS2clouds).median();
        if (s2_image.bandNames().size().getInfo() === 0) return null;
        return s2_image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    };

    // 3. Calculation
    const ndvi_image_2021 = getNdvi(startDate1, endDate1, geometry);
    const ndvi_image_2022 = getNdvi(startDate2, endDate2, geometry);

    if (!ndvi_image_2021 || !ndvi_image_2022) {
        console.log("Empty collection for one or both periods after initial search.");
        console.log("A"); // C1 is not the correct response.
        return;
    }

    const scale = 1000;
    const commonReducer = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const stats_2021 = ndvi_image_2021.reduceRegion({
        reducer: commonReducer,
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    });

    const stats_2022 = ndvi_image_2022.reduceRegion({
        reducer: commonReducer,
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    });

    const ndvi_2021 = stats_2021.get('NDVI_mean').getInfo();
    const count_2021 = stats_2021.get('NDVI_count').getInfo();

    const ndvi_2022 = stats_2022.get('NDVI_mean').getInfo();
    const count_2022 = stats_2022.get('NDVI_count').getInfo();

    // 4. Validation & Final Answer
    console.log(`2021 Mean NDVI: ${ndvi_2021 ? ndvi_2021.toFixed(4) : 'N/A'}, Valid Pixels: ${count_2021}`);
    console.log(`2022 Mean NDVI: ${ndvi_2022 ? ndvi_2022.toFixed(4) : 'N/A'}, Valid Pixels: ${count_2022}`);

    if (count_2021 === 0 || count_2022 === 0) {
        console.log("No valid pixels after cloud masking for one or both periods.");
        console.log("C2");
        return;
    }

    if (ndvi_2021 === null || ndvi_2022 === null) {
        console.log("Calculation failed, result is null.");
        console.log("C3");
        return;
    }

    if (ndvi_2022 < ndvi_2021) {
        console.log("NDVI decreased between the two periods.");
        console.log("A");
    } else {
        console.log("NDVI did not decrease (it increased or stayed the same).");
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e.toString()}`);
    console.log("D");
});
